package com.jizza.engine.api.chat;

import java.util.UUID;

/**
 * A message the user sent. {@code conversationId} null starts a new conversation.
 * {@code clientMessageId} is generated by the client once per message, so a retried send returns
 * the turn already running instead of starting a second one.
 */
public record TurnSubmission(UUID conversationId, UUID clientMessageId, String text, String screen,
                             boolean incognito) {}
